const labels = new WeakMap();
const box = {};
const tag = Symbol("tag");

labels.set(box, "fragile").set(tag, "red");
console.log(labels.get(box), labels.get(tag));
console.log(labels.has({}));

try {
  labels.set(7, "seven");
} catch (error) {
  console.log(error.name);
}
console.log(typeof labels.size);
